from pathlib import Path
from html import escape
from format_lecon import paras
D=Path(__file__).resolve().parents[1]
def quote(n,starts):
 lines=(D/f'evidence/AIPS_{n}.txt').read_text().splitlines();out=[]
 for s in starts:
  hits=[x for x in lines if x.startswith(s)];assert len(hits)==1,(n,s,len(hits));out.append('<p>« '+escape(hits[0])+' »</p>')
 return '<blockquote>'+'\n'.join(out)+'</blockquote>'
def cycloplegie(l):
 d=paras('Cyclogyl est un collyre diagnostique au cyclopentolate, antimuscarinique. La mydriase dilate la pupille ; la cycloplégie bloque l’accommodation. Une pupille large ne prouve pas à elle seule une cycloplégie suffisante. La notice suisse de mai 2021, autorisation 32634, prime sur les schémas étrangers.')
 d+=quote('32634',["Instiller 1 ou 2 gouttes de Cyclogyl 0,5% ou 1,0%", "Instiller 1 ou 2 gouttes de Cyclogyl 0,5% ou 1%", "Instiller 1 goutte de Cyclogyl 0,5%", "Hypersensibilité connue", "Cyclogyl est utilisé exclusivement", "Cyclogyl ne doit pas être utilisé chez les enfants de moins", "Une sensibilité augmentée", "Le risque potentiel pour l'être humain", "Il n'est pas connu si le principe actif"])
 d+=paras('Les deux premiers paragraphes de dose concernent respectivement l’adulte, puis l’enfant et l’adolescent. Le troisième concerne les jeunes enfants autorisés par la notice ; il ne lève jamais l’interdiction avant un an. La notice ne définit pas de frontière numérique supplémentaire pour le terme jeune enfant : ne pas en inventer.', 'Vérifier angle iridocornéen, antécédents de réaction anticholinergique, épilepsie, fièvre et médicaments associés. Les antihistaminiques antimuscariniques, phénothiazines et antidépresseurs tricycliques peuvent renforcer l’effet. En cas d’agitation, confusion, convulsions, fièvre ou trouble cardiorespiratoire, arrêter les instillations et obtenir une prise en charge urgente.', 'La notice ne propose pas d’ajustement chiffré rénal ou hépatique. Ne pas en déduire une sécurité démontrée. Protéger de l’éblouissement et ne pas conduire tant que la vision ou la vigilance sont altérées. Le délai moyen de dilatation d’une brochure ne remplace pas cette règle individuelle.', 'Le guide britannique de 2012 décrit une utilisation avant six mois ; ce schéma n’est pas transposé ici. Chez le nourrisson, l’ophtalmologue choisit une stratégie diagnostique appropriée et surveillée, sans retarder l’exclusion d’une cause organique.')
 return l.subwindow('cyclogyl','Cycloplégie : Cyclogyl et sécurité suisse',d,(7,3))
def atropine(l):
 d=paras('Atropine SDU Faure est un collyre en doses unitaires à 5 mg/ml, soit 0,5 %. La notice porte le numéro d’autorisation 46994 ; 46994035 est l’identifiant documentaire du fichier. Il ne s’agit pas d’une solution injectable. L’antimuscarinique réduit l’accommodation de l’œil fixateur dans une pénalisation prescrite par le spécialiste.')
 d+=quote('46994035',["Pour paralyser l'accommodation", "Instiller 1 goutte 1 à 3 fois", "Les enfants et les petits enfants seront traités", "Glaucome et glaucome", "Hypersensibilité à l'atropine", "L'atropine doit être utilisée", "L'effet de l'atropine peut être renforcé", "Des malformations", "Interrompre l'allaitement", "Les patients doivent être rendus attentifs"])
 d+=paras('La posologie générale de la notice ne définit pas un programme universel de pénalisation : œil traité, fréquence, durée et contrôles sont individualisés. Ne pas recopier un schéma étranger au week-end ou une concentration différente en le présentant comme une dose de cette notice.', 'La surveillance compare l’acuité des deux yeux et vérifie que l’œil pénalisé ne développe pas à son tour une baisse de vision. Prévenir l’entourage des signes anticholinergiques : bouche sèche, rougeur, fièvre, agitation, accélération du pouls ou difficulté à uriner. Une suspicion d’intoxication impose l’arrêt et un avis urgent.', 'Un eczéma palpébral conduit à réévaluer et remplacer le produit selon le prescripteur. La durée des effets oculaires peut être prolongée ; l’arrêt ne rend pas immédiatement la conduite sûre. Aucun palier posologique rénal ou hépatique n’est fourni dans cette notice.', 'Les mesures optiques et l’occlusion restent des alternatives selon le type d’amblyopie et la tolérance. La pénalisation traite le développement visuel ; elle ne remplace ni le bilan de la cause ni, lorsqu’elle est indiquée, la chirurgie d’alignement.')
 return l.subwindow('atropine','Atropine : pénalisation et précautions',d,(8,6))
def mestinon(l):
 d=paras('La pyridostigmine inhibe l’acétylcholinestérase et améliore la transmission neuromusculaire. Elle traite les symptômes sans supprimer l’auto-immunité. La forme décrite ici est la dragée de Mestinon à 60 mg par voie orale. Elle ne doit pas être confondue avec le comprimé de 10 mg ou la forme retard de 180 mg de la notice commune de juin 2020.')
 d+=quote('19943',["1 dragée contient 60 mg", "Comprimés, dragées: 1 à 3 dragées 2 à 4 fois", "Comprimés, dragées: Au cours du traitement", "Il est conseillé de choisir les heures", "La pyridostigmine est éliminée en majeure partie", "Le comprimé de 10 mg ne convient pas", "En cas d'utilisation pédiatrique", "Hypersensibilité au principe actif", "En cas d'obstruction mécanique", "Mestinon/Mestinon retard ne doit pas être administré en même temps", "Une très grande prudence est de mise", "La dose de Mestinon/Mestinon retard requise peut être diminuée", "Le médicament ne doit être utilisé pendant la grossesse", "On ne dispose que d'informations insuffisantes", "Des effets indésirables muscariniques peuvent apparaître"])
 d+=paras('La plage posologique générale citée est celle de la notice pour la myasthénie adulte ; elle ne constitue pas une dose initiale universelle de myasthénie oculaire. Le neurologue ajuste progressivement dose et horaires à la réponse et à la tolérance. La mention de doses éventuellement plus élevées ne donne pas l’autorisation d’augmenter seul le traitement.', 'La notice ne fournit pas de paliers chiffrés selon le débit de filtration rénale. Elle ne donne pas de recommandation posologique particulière pour le sujet âgé ou l’insuffisance hépatique. L’absence de palier ne dispense pas de surveiller bradycardie, hypotension, sécrétions et faiblesse.', 'Réviser les interactions avant une nouvelle prescription ou anesthésie : aminoglycosides, médicaments influençant la transmission neuromusculaire, antiarythmiques et myorelaxants. La méthylcellulose peut empêcher l’absorption. Les antimuscariniques modifient les effets muscariniques et peuvent ralentir l’absorption.', 'Une aggravation avec diarrhée, sueurs, salivation, myosis, fasciculations ou sécrétions bronchiques peut traduire un excès cholinergique. Une crise myasthénique peut aussi produire une faiblesse respiratoire : obtenir une évaluation urgente, sans auto-ajustement. En cas de crise cholinergique, l’arrêt du médicament et le soutien respiratoire relèvent de la prise en charge urgente.', 'Le schéma néonatal de la notice ne s’applique pas automatiquement à un enfant avec ptosis. Toute prescription pédiatrique est spécialisée, avec préparation adaptée. Pendant grossesse et allaitement, le suivi neurologique et obstétrical doit tenir compte des variations de la maladie et des précautions citées.', 'La diplopie, le myosis ou les troubles de l’accommodation peuvent altérer la conduite. La forme retard ne se substitue pas comprimé pour dragée sans recalcul et décision médicale. L’identification du conditionnement et la concordance avec la notice en vigueur sont vérifiées à la prescription et à la délivrance.')
 return l.subwindow('mestinon','Mestinon : dose suisse et sécurité',d,(14,13,21))
def tepezza(l):
 d=paras('Le téprotumumab bloque le récepteur du facteur de croissance analogue à l’insuline de type 1. TEPEZZA est une poudre pour perfusion en flacon de 500 mg, autorisation suisse 69795, notice de mars 2026. Son indication suisse vise la maladie active modérée à sévère chez l’adulte, et non toute diplopie thyroïdienne.')
 d+=quote('69795',["TEPEZZA est indiqué", "TEPEZZA doit être administré sous surveillance", "La dose de TEPEZZA est déterminée", "Pour les 2 premières perfusions", "Aucune adaptation posologique n'est nécessaire chez les patients présentant une insuffisance rénale", "L'effet d'une insuffisance hépatique", "La sécurité et l'efficacité de TEPEZZA chez les enfants", "· Hypersensibilité au principe actif", "· Grossesse", "L'audition des patients doit être évaluée", "Avant la perfusion, une augmentation", "TEPEZZA peut entraîner l'aggravation", "Les femmes en âge de procréer doivent", "On ignore si le téprotumumab passe"])
 d+=paras('Surveiller pendant la perfusion et durant les 90 minutes suivantes, comme le précise la notice. Interrompre ou arrêter la perfusion selon la gravité d’une réaction et traiter dans une structure équipée. Une prémédication et un ralentissement des perfusions suivantes sont discutés après une réaction aux premières administrations.', 'Une perte auditive peut être sévère et parfois permanente. Évaluer l’audition avant, pendant et après le traitement ; une modification doit être signalée immédiatement. Contrôler glycémie et pression artérielle, et surveiller les symptômes digestifs chez un patient avec maladie inflammatoire intestinale.', 'La grossesse est contre-indiquée et une contraception efficace se poursuit pendant six mois après la dernière administration. Ne pas utiliser pendant l’allaitement. L’indication ne s’étend pas aux moins de 18 ans. Les données rénales sévères et hépatiques modérées à sévères restent insuffisantes.', 'Aucune étude formelle d’interactions n’a été menée. Le médicament ne se perfuse pas avec d’autres produits dans la même tubulure et ne s’administre pas en bolus. La préparation et la dilution relèvent du protocole pharmaceutique hospitalier. Un second cycle ne doit pas être présenté comme une stratégie à efficacité et sécurité établies.', 'Le choix se discute avec l’équipe spécialisée selon activité, gravité, comorbidités et objectifs. Une autorisation ne prouve ni disponibilité immédiate ni remboursement individuel, et ne remplace pas le traitement urgent d’une neuropathie optique.')
 return l.subwindow('tepezza','Téprotumumab : indication et sécurité suisses',d,(22,12))
def methylpred(l):
 d=paras('La méthylprednisolone est un glucocorticoïde anti-inflammatoire et immunosuppresseur. La notice suisse Solu-MEDROL d’août 2025 décrit une poudre avec solvant, en flacons de 500 mg ou 1 g, autorisation 35112. Les schémas spécifiques d’orbitopathie ci-dessous proviennent d’EUGOGO et ne sont pas présentés comme des posologies AIPS spécifiques de cette indication.')
 d+=paras('Pour une forme active modérée à sévère, EUGOGO 2021 décrit 0,5 g intraveineux une fois par semaine pendant six semaines. Il poursuit avec 0,25 g une fois par semaine pendant six semaines, soit 4,5 g au total. Le schéma plus élevé de 7,5 g est réservé à certains cas plus sévères de ce groupe ; il ne s’applique pas automatiquement à toute diplopie.', 'Pour une neuropathie optique dysthyroïdienne, EUGOGO décrit des doses intraveineuses de 0,5–1 g sur trois administrations, consécutives ou de préférence un jour sur deux. L’évaluation spécialisée est immédiate. En cas de réponse absente ou insuffisante dans les une à deux semaines, la décompression urgente est indiquée ; une détérioration ne doit pas attendre ce délai.', 'La dose cumulée ne doit pas dépasser 8 g par cycle selon EUGOGO. Ce plafond ne dispense pas d’évaluer le risque de chaque perfusion. Une hépatite récente, une atteinte hépatique significative, une morbidité cardiovasculaire sévère ou une hypertension non contrôlée contre-indiquent ce traitement intraveineux dans cette recommandation ; contrôler le diabète avant traitement.')
 d+=quote('35112',["La durée d'administration des doses initiales", "Chez les patients atteints d'insuffisance hépatique grave", "Chez les patients souffrant d'une insuffisance rénale", "· Mycoses systémiques", "· Hypersensibilité à la méthylprednisolone", "L'administration de vaccins vivants", "Les corticostéroïdes tels que la méthylprednisolone", "Puisque la méthylprednisolone passe dans le lait maternel"])
 d+=paras('Les durées minimales d’administration citées sont celles de l’AIPS ; elles ne définissent pas un protocole complet de perfusion. La notice signale des complications cardiaques lors d’administration rapide de fortes doses et des lésions hépatiques parfois graves après doses élevées.', 'Avant et pendant traitement, surveiller pression artérielle, glycémie, électrolytes, fonction hépatique et signes infectieux. Évaluer antécédents psychiatriques, risque osseux, risque digestif et interactions, notamment avec les inhibiteurs ou inducteurs du CYP3A4. Les corticoïdes peuvent masquer une infection.', 'Les formulations citées contiennent de l’alcool benzylique et ne conviennent pas aux prématurés et nouveau-nés. Ne pas extrapoler ce schéma adulte à l’enfant. La grossesse impose une évaluation rigoureuse ; la notice citée demande de ne pas allaiter pendant l’utilisation. Prévoir la stratégie de diminution et la prévention de l’insuffisance surrénale selon durée et exposition antérieure.', 'Le mycophénolate est associé aux corticoïdes dans la stratégie européenne de première ligne pour certaines formes actives modérées à sévères. Sa prescription, son statut d’indication et ses précautions reproductives nécessitent une vérification spécifique ; aucune posologie de mycophénolate n’est fournie ici.')
 return l.subwindow('methylpred','Méthylprednisolone : recommandation européenne et sécurité AIPS',d,(12,23))
